-- Complete, production-derived function permission manifest and first grant-reduction batch.
-- The matching readable manifest is config/database-function-permissions.json.
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;

create table if not exists private.function_permission_manifest(
 signature text primary key,
 function_name text not null,
 classification text not null check(classification in('anonymous_token_public','authenticated_self_service','staff_aal2','service_worker','trigger_internal')),
 allowed_roles text[] not null,
 security_definer boolean not null,
 fixed_search_path boolean not null,
 rationale text not null,
 reviewed_at date not null default date '2026-08-03'
);
truncate private.function_permission_manifest;

alter default privileges for role postgres in schema public revoke execute on functions from public,anon,authenticated,service_role;

do $permissions$
declare f record;m private.function_permission_manifest%rowtype;live_count integer;
begin
 select count(*) into live_count from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public';
 if live_count<>(select count(*) from private.function_permission_manifest) then raise exception 'Function permission manifest count mismatch: % live, % manifested',live_count,(select count(*) from private.function_permission_manifest);end if;
 for f in select format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) signature,p.prosecdef,coalesce(array_to_string(p.proconfig,','),'') like '%search_path=%' fixed_search_path from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
 loop
  select * into m from private.function_permission_manifest where signature=f.signature;
  if not found then raise exception 'Unmanifested public function: %',f.signature;end if;
  if m.security_definer<>f.prosecdef or m.fixed_search_path<>f.fixed_search_path then raise exception 'Function security metadata drift: %',f.signature;end if;
  execute format('revoke all privileges on function %s from public,anon,authenticated,service_role',f.signature);
  if 'anon'=any(m.allowed_roles) then execute format('grant execute on function %s to anon',f.signature);end if;
  if 'authenticated'=any(m.allowed_roles) then execute format('grant execute on function %s to authenticated',f.signature);end if;
  if 'service_role'=any(m.allowed_roles) then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end
$permissions$;

revoke all on table private.function_permission_manifest from public,anon,authenticated,service_role;
comment on table private.function_permission_manifest is 'Versioned source of truth for public-schema function execution privileges.';

create or replace function private.assert_function_permission_manifest() returns void language plpgsql security definer set search_path=pg_catalog,private as $assert$
declare missing text;unexpected text;
begin
 select string_agg(l.signature,', ' order by l.signature) into missing from(select format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public')l left join private.function_permission_manifest m using(signature) where m.signature is null;
 select string_agg(m.signature,', ' order by m.signature) into unexpected from private.function_permission_manifest m left join(select format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public')l using(signature) where l.signature is null;
 if missing is not null or unexpected is not null then raise exception 'Function permission manifest drift. Missing: %. Unexpected: %.',coalesce(missing,'none'),coalesce(unexpected,'none');end if;
end
$assert$;
revoke all on function private.assert_function_permission_manifest() from public,anon,authenticated,service_role;

